Q: Having problems with using the hamburger menu A: <p>I made some changes, as can be seen below. You can further tweak around with the values. And also you either use Font Awesome, or Google Fonts, for the icons to show up, but not both.
I added an extra animation to the burger menu, and the search field is hidden by default and only visible on clicking the magnifying glass.</p>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>const menuButton = document.querySelector(".menu-toggle");
const mainNav = document.querySelector(".main-nav");

menuButton?.addEventListener("click", () =&gt; {
  const isOpen = menuButton.classList.toggle("is-active");

  mainNav?.classList.toggle("open", isOpen);

  menuButton.setAttribute("aria-expanded", String(isOpen));
  menuButton.setAttribute(
    "aria-label",
    isOpen ? "Close menu" : "Open menu"
  );
});

document.querySelectorAll(".main-nav a").forEach((link) =&gt; {
  link.addEventListener("click", () =&gt; {
    mainNav?.classList.remove("open");
    menuButton?.classList.remove("is-active");

    menuButton?.setAttribute("aria-expanded", "false");
    menuButton?.setAttribute("aria-label", "Open menu");
  });
});

const observer = new IntersectionObserver((entries) =&gt; {
  entries.forEach(entry =&gt; {
    if (entry.isIntersecting) entry.target.classList.add('visible');
  });
}, {
  threshold: 0.12
});

document.querySelectorAll('.reveal').forEach(el =&gt; observer.observe(el));

function toggleDiv() {
  const div = document.getElementById("search");
  // Toggle between hidden and visible
  if (div.style.display === "none" || div.style.display === "") {
    div.style.display = "block";
  } else {
    div.style.display = "none";
  }
}</code></pre>
<pre class="snippet-code-css lang-css prettyprint-override"><code>* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  font-family: "Space Grotesk", sans-serif;
  list-style: none;
  text-decoration: none;
}


:root {
  --default-white-color: #fff;
  --default-black-color: #000;
  --primary-color: #f59e0b;
  --color-red-500: #fb2c36;
  --color-gray-100: #f3f4f6;
  --color-gray-200: #e5e7eb;
  --color-gray-300: #d1d5dc;
  --color-gray-400: #99a1af;
  --color-gray-700: #364153;
  --color-gray-900: #101828;
}

/* NAV STYLE START  */

.container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 1.5em;
  box-shadow: 1px 0px 4px 5px var(--color-gray-200);
}


.ls {
  display: flex;
  align-items: center;
  gap: 1.875em;
}

.ls .logo a {
  color: var(--color-gray-900);
}

.ls .logo {
  font-size: 1.5rem;
  text-transform: uppercase;
}

.ls .logo .c-logo {
  color: var(--primary-color);
}

#rightWrapper {
  display: flex;
  gap: 20px;
  align-content: center;
  align-items: center;
  flex-wrap: wrap;
}

.contact a {
  color: var(--color-gray-700);
  padding: .5em 1em;
  font-size: 0.875em;
  border-radius: 1.875em;
}

.search input {
  padding: .5em;
  width: 10em;
  border-radius: 1.875em;
  border: 1px solid var(--color-gray-400);
  border-top-left-radius: 0px;
  border-bottom-left-radius: 0px;
  border-left: none;
}

#search {
  display: none;
}

.search i {
  float: left;
}

.cart span {
  padding: 0.625em;
  border-radius: 50%;
}

.cart:hover {
  cursor: pointer;
  background-color: var(--color-gray-100);
  border-radius: 50%;
}

.sign-btns {
  display: flex;
  gap: 1.5em;
  flex-wrap: wrap;
}

.sign-btns a {
  color: var(--default-black-color);
  width: 100%;
  text-align: center;
}

.sign-btns .sign-in:hover {
  color: var(--primary-color);
}

.contact span {
  width: 100%;
  display: block;
  padding-bottom: 0.625em;
  border-bottom: 1px solid var(--color-gray-300);
}

.sign-in,
.sign-up {
  width: 100%;
  display: block;
  padding: 0.625em;
  border-radius: 1.875em;
  box-shadow: 0px 0px 7px -3px;
}

.sign-btns .sign-up {
  background-color: var(--primary-color);
}

.menu-toggle {
  display: none;
  background: none;
  border: 0;
  margin-left: auto;
}

.menu-toggle span {
  display: block;
  width: 25px;
  height: 2px;
  margin: 5px;
}

.menu-toggle {
  display: none;
  position: relative;
  margin-left: auto;
  padding: 23px;
  border: 0;
  border-radius: 50%;
  background: transparent;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  touch-action: manipulation;
  transition:
    background-color 0.25s ease,
    transform 0.15s ease;
}

.menu-toggle span {
  position: absolute;
  left: 41%;
  width: 23px;
  height: 2px;
  border-radius: 999px;
  background: #003871;
  transform: translateX(-50%);
  transition:
    top 0.3s ease,
    transform 0.3s ease,
    opacity 0.2s ease,
    background-color 0.3s ease;
  margin-top: 0px;
}

.menu-toggle span:nth-child(1) {
  top: 15px;
}

.menu-toggle span:nth-child(2) {
  top: 23px;
}

.menu-toggle span:nth-child(3) {
  top: 31px;
}

/* touch feedback */
.menu-toggle:active {
  transform: scale(0.9);
  background: rgba(156, 199, 230, 0.28);
}

/*Open state of burger */
.menu-toggle.is-active span:nth-child(1) {
  top: 23px;
  transform: translateX(-50%) rotate(45deg);
  background: black;
}

.menu-toggle.is-active span:nth-child(2) {
  opacity: 0;
  transform: translateX(-50%) scaleX(0);
}

.menu-toggle.is-active span:nth-child(3) {
  top: 23px;
  transform: translateX(-50%) rotate(-45deg);
  background: black;
}

.menu-toggle:focus-visible {
  outline: 3px solid rgba(156, 199, 230, 0.8);
  outline-offset: 3px;
}

.menu-toggle.is-active {
  border: 2px solid var(--primary-color);
}

@media (max-width: 900px) {
  .reveal {
    opacity: 0;
    transform: translateY(24px);
    transition: .8s ease;
  }

  .reveal.visible {
    opacity: 1;
    transform: none;
  }

  .main-nav,
  .nav-cta {
    display: none;
  }

  .main-nav.open {
    display: flex;
    position: absolute;
    top: 88px;
    left: 20px;
    right: 20px;
    flex-direction: column;
    padding: 24px;
    background: #fff;
    border-radius: 18px;
    box-shadow: var(--shadow);
  }

  .menu-toggle {
    display: block;
  }
}

/* anim reduce */
@media (prefers-reduced-motion: reduce) {

  .menu-toggle,
  .menu-toggle span {
    transition: none;
  }
}</code></pre>
